package main

import (
    "bytes"
    "flag"
    "fmt"
    "io"
    "io/ioutil"
    "os"
    "strconv"
    "strings"
    "text/template"
    "time"
)

var helpText = `Process text files with Go templates

Usage:
  gomplate [flags]

Flags:
  -d, --datasource datasource        datasource in alias=URL form. Specify multiple times to add multiple sources.
  -H, --datasource-header header     HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.
  -c, --context datasource           pre-load a datasource into the context, in alias=URL form. Use the special alias ` + "`." + ` to set the root context.
      --plugin strings               plug in an external command as a function in name=path form. Can be specified multiple times
  -f, --file file                    Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])
  -i, --in string                    Template string to process (alternative to --file and --input-dir)
      --input-dir directory          directory which is examined recursively for templates (alternative to --file and --in)
      --exclude strings              glob of files to not parse
      --exclude-processing strings   glob of files to be copied without parsing
      --include strings              glob of files to parse
  -o, --out file                     output file name. Omit to use standard output. (default [-])
  -t, --template strings             Additional template file(s)
      --output-dir directory         directory to store the processed templates. Only used for --input-dir (default ".")
      --output-map string            Template string to map the input file to an output path
      --chmod string                 set the mode for output file(s). Omit to inherit from input file(s)
      --exec-pipe                    pipe the output to the post-run exec command
      --left-delim delimiter         override the default left-delimiter [$GOMPLATE_LEFT_DELIM] (default "{{")
      --right-delim delimiter        override the default right-delimiter [$GOMPLATE_RIGHT_DELIM] (default "}}")
      --missing-key string           Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value> (default "error")
      --experimental                 enable experimental features [$GOMPLATE_EXPERIMENTAL]
  -V, --verbose                      output extra information about what gomplate is doing
      --config string                config file (overridden by commandline flags) (default ".gomplate.yaml")
  -h, --help                         help for gomplate
  -v, --version                      version for gomplate
`

type multiFlag []string

func (m *multiFlag) String() string { return strings.Join(*m, ",") }
func (m *multiFlag) Set(value string) error { *m = append(*m, value); return nil }

func envMap() map[string]string {
    env := map[string]string{}
    for _, e := range os.Environ() {
        parts := strings.SplitN(e, "=", 2)
        if len(parts) == 2 {
            env[parts[0]] = parts[1]
        }
    }
    return env
}

func toFloat(v interface{}) (float64, error) {
    switch t := v.(type) {
    case int:
        return float64(t), nil
    case int64:
        return float64(t), nil
    case float64:
        return t, nil
    case string:
        return strconv.ParseFloat(t, 64)
    default:
        return 0, fmt.Errorf("unsupported type")
    }
}

func mulFunc(args ...interface{}) (interface{}, error) {
    if len(args) < 2 {
        return nil, fmt.Errorf("mul requires at least two args")
    }
    // multiply as integers if all ints
    prod := 1.0
    for _, a := range args {
        f, err := toFloat(a)
        if err != nil { return nil, err }
        prod *= f
    }
    // If all args are integers (no decimal part), return integer
    allInt := true
    for _, a := range args {
        switch v := a.(type) {
        case int, int64:
        default:
            // for strings or floats, check if numeric string represents integer
            fv, err := toFloat(a)
            if err != nil { allInt = false; break }
            if fv != float64(int64(fv)) { allInt = false }
        }
    }
    if allInt {
        return int64(prod), nil
    }
    return prod, nil
}

func main() {
    // Define flags
    var datasources multiFlag
    var dsheaders multiFlag
    var contexts multiFlag
    var plugins multiFlag
    var file string
    var in string
    var inputDir string
    var excludes multiFlag
    var excludeProcessing multiFlag
    var includes multiFlag
    var outFile string
    var templates multiFlag
    var outputDir string
    var outputMap string
    var chmodStr string
    var execPipe bool
    var leftDelim string
    var rightDelim string
    var missingKey string
    var experimental bool
    var verbose bool
    var config string
    var showHelp bool
    var showVersion bool

    flag.Var(&datasources, "datasource", "datasource in alias=URL form. Specify multiple times to add multiple sources.")
    flag.Var(&datasources, "d", "datasource in alias=URL form. Specify multiple times to add multiple sources.")
    flag.Var(&dsheaders, "datasource-header", "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
    flag.Var(&dsheaders, "H", "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
    flag.Var(&contexts, "context", "pre-load a datasource into the context, in alias=URL form. Use the special alias '.' to set the root context.")
    flag.Var(&contexts, "c", "pre-load a datasource into the context, in alias=URL form. Use the special alias '.' to set the root context.")
    flag.Var(&plugins, "plugin", "plug in an external command as a function in name=path form. Can be specified multiple times")
    flag.StringVar(&file, "file", "", "Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])")
    flag.StringVar(&file, "f", "", "Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])")
    flag.StringVar(&in, "in", "", "Template string to process (alternative to --file and --input-dir)")
    flag.StringVar(&in, "i", "", "Template string to process (alternative to --file and --input-dir)")
    flag.StringVar(&inputDir, "input-dir", "", "directory which is examined recursively for templates (alternative to --file and --in)")
    flag.Var(&excludes, "exclude", "glob of files to not parse")
    flag.Var(&excludeProcessing, "exclude-processing", "glob of files to be copied without parsing")
    flag.Var(&includes, "include", "glob of files to parse")
    flag.StringVar(&outFile, "out", "", "output file name. Omit to use standard output. (default [-])")
    flag.Var(&templates, "template", "Additional template file(s)")
    flag.Var(&templates, "t", "Additional template file(s)")
    flag.StringVar(&outputDir, "output-dir", ".", "directory to store the processed templates. Only used for --input-dir (default \".\")")
    flag.StringVar(&outputMap, "output-map", "", "Template string to map the input file to an output path")
    flag.StringVar(&chmodStr, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
    flag.BoolVar(&execPipe, "exec-pipe", false, "pipe the output to the post-run exec command")
    flag.StringVar(&leftDelim, "left-delim", "{{", "override the default left-delimiter [$GOMPLATE_LEFT_DELIM] (default \"{{\")")
    flag.StringVar(&rightDelim, "right-delim", "}}", "override the default right-delimiter [$GOMPLATE_RIGHT_DELIM] (default \"}}\")")
    flag.StringVar(&missingKey, "missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value> (default \"error\")")
    flag.BoolVar(&experimental, "experimental", false, "enable experimental features [$GOMPLATE_EXPERIMENTAL]")
    flag.BoolVar(&verbose, "verbose", false, "output extra information about what gomplate is doing")
    flag.StringVar(&config, "config", ".gomplate.yaml", "config file (overridden by commandline flags) (default \".gomplate.yaml\")")
    flag.BoolVar(&showHelp, "help", false, "help for gomplate")
    flag.BoolVar(&showHelp, "h", false, "help for gomplate")
    flag.BoolVar(&showVersion, "version", false, "version for gomplate")
    flag.BoolVar(&showVersion, "v", false, "version for gomplate")

    flag.Parse()

    if showHelp {
        fmt.Print(helpText)
        return
    }
    if showVersion {
        fmt.Println("gomplate version 0.0.0")
        return
    }

    var tplSrc string
    if in != "" {
        tplSrc = in
    } else if file != "" {
        b, err := ioutil.ReadFile(file)
        if err != nil { fmt.Fprintf(os.Stderr, "failed to read file: %v\n", err); os.Exit(1) }
        tplSrc = string(b)
    } else if inputDir != "" {
        // not implemented: just error
        fmt.Fprintln(os.Stderr, "input-dir not implemented")
        os.Exit(1)
    } else {
        b, err := ioutil.ReadAll(os.Stdin)
        if err != nil { fmt.Fprintf(os.Stderr, "failed to read stdin: %v\n", err); os.Exit(1) }
        tplSrc = string(b)
    }

    funcMap := template.FuncMap{
        "mul": func(a ...interface{}) (interface{}, error) { return mulFunc(a...) },
        // provide ds func placeholder
        "ds": func(alias string) (map[string]interface{}, error) { return map[string]interface{}{}, nil },
    }

    // Prepare context
    ctx := map[string]interface{}{
        "Env": envMap(),
        "Now": time.Now,
    }

    tpl := template.New("gomplate").Funcs(funcMap)
    tpl = tpl.Delims(leftDelim, rightDelim)

    t, err := tpl.Parse(tplSrc)
    if err != nil {
        fmt.Fprintf(os.Stderr, "template parse error: %v\n", err)
        os.Exit(1)
    }

    var outBuf bytes.Buffer
    if err := t.Execute(&outBuf, ctx); err != nil {
        // Print an error similar to original but simpler
        fmt.Printf("%s", outBuf.String())
        // Emit a JSON-like error line
        fmt.Fprintf(os.Stderr, "{\"time\":\"%s\",\"level\":\"ERROR\",\"msg\":\"\",\"err\":\"%s\"}\n", time.Now().UTC().Format(time.RFC3339Nano), err.Error())
        os.Exit(1)
    }

    // output to file or stdout
    if outFile != "" {
        if err := ioutil.WriteFile(outFile, outBuf.Bytes(), 0644); err != nil {
            fmt.Fprintf(os.Stderr, "failed to write output: %v\n", err); os.Exit(1)
        }
    } else {
        io.Copy(os.Stdout, &outBuf)
    }
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
# Build the gomplate-like executable
exec 2>&1
which go >/dev/null 2>&1 || { echo "go not found"; exit 1; }
GOOS=$(uname | tr '[:upper:]' '[:lower:]')
# Build to ./executable
go build -o executable main.go
EOF

chmod +x compile.sh

# Build now
./compile.sh

# Run basic tests
echo "--help output:"; ./executable --help | sed -n '1,120p'

echo "--version:"; ./executable --version

echo 'the answer is: {{ mul 6 7 }}' | ./executable

"}

